"use strict";
// logger.lib.civet

import {cyan, red, yellow, stripAnsiCode} from '@std/fmt/colors'
import {existsSync} from '@std/fs'

export let logWidth = 78

export enum TLogLevel {
	SILENT,    // 0
	TESTING,   // 1
	INFO,      // 2
	DEBUG      // 3
	}

let lLogLevels: TLogLevel[] = [TLogLevel.INFO]
let logLevel: TLogLevel = TLogLevel.INFO

let boxLevel: number = 0

// ---------------------------------------------------------------------------

export const inUnitTest = () => {

	return lLogLevels[0] === TLogLevel.TESTING
}

// ---------------------------------------------------------------------------

export const beginBox = (title: (string | undefined)): void => {

	const width = logWidth - 2*boxLevel
	if (title === undefined) {
		LOG(yellow('┌' + '─'.repeat(width-1)))
	}
	else {
		LOG(yellow('┌' + '─'.repeat(width-1)))
		LOG(yellow('│') + ' ' + cyan(title))
		LOG(yellow('├' + '─'.repeat(width-1)))
	}
	boxLevel += 1
	return
}

// ---------------------------------------------------------------------------

export const endBox = (): void => {

	if (boxLevel === 0) {
		throw new Error("boxLevel = 0 in endBox()")
	}
	boxLevel -= 1
	const width = logWidth - 2*boxLevel
	LOG(yellow('└' + '─'.repeat(width-1)))
	return
}

// ---------------------------------------------------------------------------

const curLevelLowerThan = (level: TLogLevel): boolean => {

	return (logLevel < level)
}

// ---------------------------------------------------------------------------

export const logLevelStr = (level: TLogLevel): string => {

	switch(level) {
		case TLogLevel.SILENT: { return 'silent'
		}
		case TLogLevel.TESTING: { return 'testing'
		}
		case TLogLevel.INFO: { return 'info'
		}
		case TLogLevel.DEBUG: { return 'debug'
		}
	}
	return 'unknown'
}

// ---------------------------------------------------------------------------

export const logLevelFromStr = (level: string): TLogLevel => {

	switch(level) {
		case 'silent': { return TLogLevel.SILENT
		}
		case 'testing': { return TLogLevel.TESTING
		}
		case 'info': { return TLogLevel.INFO
		}
		case 'debug': { return TLogLevel.DEBUG
		}
		default: {
			throw new Error(`No such log level: ${level}`)
		}
	}
}

// ---------------------------------------------------------------------------

let indentLevel = 0
let lLogLines: string[] = []   // none should include \n

export const INDENT = Symbol('indent')
export const UNDENT = Symbol('undent')

// ---------------------------------------------------------------------------
//   debug files
// ---------------------------------------------------------------------------

const setDebugFiles = new Set<string>()

// ---------------------------------------------------------------------------

const debugFilePath = (stub: string): string => {

	return `./logs/${stub}.log`
}

// ---------------------------------------------------------------------------

export const openDebugFile = (
		stub: string
		): void => {

	const path = debugFilePath(stub)
	setDebugFiles.add(path)
	return
}

// ---------------------------------------------------------------------------

export const removeDebugFile = (stub: string): void => {

	const path = debugFilePath(stub)
	if (existsSync(path)) {
		Deno.removeSync(path)
	}
	return
}

// ---------------------------------------------------------------------------

export const appendDebugFile = (
		...lItems: unknown[]
		): void => {

	for (const item of lItems) {
		const block = (
			  (typeof item === 'string')
			? stripAnsiCode(item)
			: toJSON(item)
			)
		for (const path of setDebugFiles) {
			Deno.writeTextFileSync(path, block + "\n", {append: true})
		}
	}
	return
}

// ---------------------------------------------------------------------------

export const closeDebugFile = (stub: string): void => {

	const path = `src/logs/${stub}.log`
	setDebugFiles.delete(path)
	return
}

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------

export const curLogLevel = (): string => {

	return logLevelStr(logLevel)
}

// ---------------------------------------------------------------------------

export const initLogLevel = (
		level: TLogLevel | string
		): void => {

	if (typeof level === 'string') {
		level = logLevelFromStr(level)
	}
	lLogLevels = [level]
	logLevel = level
	console.log(`INITIAL LOG LEVEL set to ${logLevelStr(level)}`)
	return
}

// ---------------------------------------------------------------------------

export const pushLogLevel = (
		level: TLogLevel | string
		): void => {

	if (typeof level === 'string') {
		level = logLevelFromStr(level)
	}
	lLogLevels.push(level)
	logLevel = level
	return
}

// ---------------------------------------------------------------------------

export const popLogLevel = (): void => {

	if (lLogLevels.length === 0) {
		throw new Error("Empty lLogLevels in pop()")
	}
	logLevel = lLogLevels.pop() || TLogLevel.INFO
	if (logLevel === undefined) {
		throw new Error("Empty lLogLevels in pop()")
	}
	return
}

// ---------------------------------------------------------------------------

const toJSON = (item: unknown): string => {

	return JSON.stringify(item, null, 3)
}

// ---------------------------------------------------------------------------

export const stringFits = (
		str: string,
		width: number = logWidth
		): boolean => {

	return (str.length <= width)
}

// ---------------------------------------------------------------------------

export const LOG = (
		item: unknown
		): void => {

	if (logLevel !== TLogLevel.SILENT) {
		logItem(item)
	}
	return
}

// ---------------------------------------------------------------------------

export const WARN = (
		msg: string,
		label: string = 'WARNING'
		): void => {

	if (curLevelLowerThan(TLogLevel.TESTING)) {
		return
	}
	logItem(yellow(label) + ': ' + msg)
	return
}

// ---------------------------------------------------------------------------

export const DBG = (
		item: unknown
		): void => {

	// --- if a debug file is defined, output even if
	//     current log level is not 'debug'
	appendDebugFile(item)

	if (curLevelLowerThan(TLogLevel.DEBUG)) {
		return
	}
	logItem(item)
	return
}

// ---------------------------------------------------------------------------

export const ERR = (
		err: unknown,
		label: string = 'ERROR'
		): void => {

	const msg = (
		  (err instanceof Error)   ? err.message
		: (typeof err === 'string') ? err
		:                            'Unknown error'
		)

	// --- if a debug file is defined, output even if
	//     current log level is not 'debug'
	appendDebugFile(msg)

	logItem(red(label) + ': ' + msg)
	return
}

// ---------------------------------------------------------------------------

export const toConsole = (
		block: string,
		label: string = ''
		): void => {

	if (label) {
		const ch = '='
		const str20 = ch.repeat(20)
		const str40 = ch.repeat(40)
		console.log(str20 + ' ' + label + ' ' + str20)
		console.log(block.replaceAll('\t', '   '))
		console.log(str40)
	}
	else {
		console.log(block.replaceAll('\t', '   '))
	}
	return
}

// ---------------------------------------------------------------------------

export const toInternalLog = (
		block: string,
		label: string = ''
		): void => {

	if (label) {
		const ch = '='
		const str20 = ch.repeat(20)
		const str40 = ch.repeat(40)
		lLogLines.push(str20 + ' ' + label + ' ' + str20)
		lLogLines.push(stripAnsiCode(block))
		lLogLines.push(str40)
	}
	else {
		lLogLines.push(stripAnsiCode(block))
	}
	return
}

// ---------------------------------------------------------------------------

const logItem = (
		item: unknown,
		color: (string | undefined) = undefined,
		label: (string | undefined) = undefined
		): void => {

	if (item === INDENT) {
		indentLevel += 1
		return
	}
	if (item === UNDENT) {
		if (indentLevel > 0) {
			indentLevel -= 1
		}
		return
	}

	const block = unknownToString(item)
	for (const str of block.split('\n')) {
		const line = (
			  yellow('│ ').repeat(boxLevel)
			+ '\t'.repeat(indentLevel)
			+ str.replace(/\s+$/, '')
			)

		// --- Anything going to the console has TABs replaced
		// --- In TESTING level, no output to console
		if (!inUnitTest()) {
			toConsole(line)
		}

		// --- Anything going to internal log has ANSI codes stripped
		toInternalLog(line)
	}

	return
}

// ---------------------------------------------------------------------------
// --- Make sure lines have no trailing whitespace
//     decolorize if in a unit test

export const getLog = (): string => {

	if (inUnitTest()) {
		return stripAnsiCode(lLogLines.join('\n'))
	}
	else {
		return lLogLines.join('\n')
	}
}

// ---------------------------------------------------------------------------

export const clearLog = (width: number = 78): void => {

	if (width < 1) {
		throw new Error(`Bad width: ${width}`)
	}
	logWidth = width
	lLogLines.length = 0
	boxLevel = 0
	return
}

// ---------------------------------------------------------------------------

const unknownToString = (x: unknown): string => {

	return (
		  (typeof x === 'string') ? x
		: (x === undefined)       ? 'undef'
		: (x === null)            ? 'null'
		:                          JSON.stringify(x)
		)
}

